# Build a graph where nodes are changes_to_2 and edges exist if connected via 8-path
from collections import deque

def find_connected_chunks(cells):
    # cells is a list of positions that changed
    visited = set()
    chunks = []

    for start in cells:
        if start in visited:
            continue
        chunk = []
        queue = deque([start])
        while queue:
            pos = queue.popleft()
            if pos in visited:
                continue
            visited.add(pos)
            chunk.append(pos)
            r, c = pos
            for nr, nc in [(r+1,c), (r-1,c), (r,c+1), (r,c-1), 
                          (r+1,c+1), (r+1,c-1), (r-1,c+1), (r-1,c-1)]:
                if 0 <= nr < 10 and 0 <= nc < 26:
                    if (nr, nc) in cells:
                        if (nr, nc) not in visited:
                            queue.append((nr, nc))
                        if (nr, nc) in four_positions:
                            queue.append((nr, nc))
        chunks.append(chunk)

    return chunks

