def bfs_from_fours():
    min_dist = {}
    source = {}
    for r in range(10):
        for c in range(26):
            min_dist[(r,c)] = float('inf')
            source[(r,c)] = None

    # Start BFS from all 4 positions simultaneously
    queue = []
    for r in range(10):
        for c in range(26):
            if input_grid[r][c] == 4:
                min_dist[(r,c)] = 0
                queue.append((r, c))

    while queue:
        r, c = queue.pop(0)
        current_min = min_dist[(r,c)]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 10 and 0 <= nc < 26:
                if (nr, nc) not in min_dist:
                    # Shouldn't happen since we initialized
                    continue
                if (nr, nc) in [(r,c)]:
                    continue
                if min_dist[(nr, nc)] > current_min + 1:
                    min_dist[(nr, nc)] = current_min + 1
                    queue.append((nr, nc))

    return min_dist

